def transform(g):
    H,W=len(g),len(g[0])
    rmax=max(r for r,row in enumerate(g) if any(row))
    out=[[0]*W for _ in range(H)]
    for r,row in enumerate(g):
        s=rmax-r
        for c,x in enumerate(row):
            if x and 0<=c-s<W: out[r][c-s]=x
    return out
